const SLACK_WEBHOOK = '';
const ctx = $input.first().json.ctx;
const w = ctx.week, p = ctx.prev, c = ctx.coverage;
const rate = (x) => (Number(x.total) ? Math.round(100 * Number(x.incorrect) / Number(x.total)) : null);
const wr = rate(w), pr = rate(p);
const cov = Number(c.total) ? Math.round(100 * Number(c.reviewed) / Number(c.total)) : 0;
const reasonPct = Number(w.total) ? Math.round(100 * Number(w.with_reason) / Number(w.total)) : 0;
const tops = (ctx.top_accounts || []).map((a) => a.name + ' (' + a.n + ')').join(', ');
let line = ':brain: *tnAI learning · weekly digest*  -  ' + w.total + ' review' + (Number(w.total) === 1 ? '' : 's') + ' by ' + w.reviewers + ' reviewer' + (Number(w.reviewers) === 1 ? '' : 's') + ' this week';
line += '  ·  ' + reasonPct + '% carried a reason';
if (wr !== null) line += '  ·  wrong-rate ' + (pr !== null ? pr + '% -> ' : '') + wr + '%';
line += '  ·  coverage ' + cov + '% of all signals  ·  ' + ctx.lessons + ' lesson' + (Number(ctx.lessons) === 1 ? '' : 's') + ' live in the classifier';
if (tops) line += '\n:memo: Most corrected this week: ' + tops;
if (Number(w.total) > 0 && reasonPct < 40) line += '\n:bulb: Reasons are thin - remind the team one tapped chip teaches more than ten bare clicks.';
if (Number(w.total) === 0) line = ':brain: *tnAI learning · weekly digest*  -  no feedback given this week. The loop only learns when the team clicks.';
return [{ json: { webhook: SLACK_WEBHOOK, line } }];
